import React from 'react';
import {
    Box as MuiBox, 
    Chip, 
    Divider,
} from '@mui/material';
import MessageBox from './MessageBox';
import Announcement from './event/Announcement';
import timeHumanReadable from '../../../../../utils/timeHumanReadable';
import Typography from '../../../../../components/Typography';

export const messageGrouping =  _messages =>  {
    const groupMss = [];
    const messages = sortMessage(_messages);
    if(messages)
        messages?.forEach(message => {
                const date = timeHumanReadable(message.createdAt, true);
                const group = groupMss?.find(({date: _date}) =>  _date === date);

                if(group)
                    group.messages?.push(message);
                else
                    groupMss.push({
                        date,
                        fullTime: (new Date(message.createdAt)).getTime(),
                        messages: [message],
                    });
            });
    return groupMss;
}

const sortMessage = _messages => {
    const messages = [..._messages || []];
    messages.sort((a, b) => 
        new Date(a?.createdAt) -
        new Date(b?.createdAt)
    );
    return messages;
};

export default function MessageGroupBoxByDate ({messages}) {
    const grouping = messageGrouping(messages);
    return grouping.map(({messages, date}) => (
        <React.Fragment key={date} >
            <Divider
                variant="middle"
                sx={{
                    position: 'relative',
                    top: '20px',
                    my: 4,
                }}
            >
                <Typography variant="caption" color="text.secondary">{date}</Typography>
            </Divider>
            {
                messages?.map((message, index, messages) => {
                    const hideAvatar = messages[index + 1]?.isMine === message?.isMine;
                    const joinBox = messages[index - 1]?.isMine === message?.isMine;
                    const key = messages.remonteId || (Date.now() + index + 1).toString(16)
                    if(message.type === 'call')
                        return (
                        <Announcement
                            {...message}
                            key={key} 
                        />)
                    if(message.type !== 'call')
                        return(
                            <MessageBox
                                key={key} 
                                {...message}
                                hideAvatar={hideAvatar}
                                joinBox={joinBox}
                            />
                        )
                    return null;
                })
            }
        </React.Fragment>
    ));
}