import Fab from '@mui/material/Fab'
import ExpandMoreOutlinedIcon from '@mui/icons-material/ExpandMoreOutlined';
import { useCallback, useEffect, useState } from 'react';
import { Zoom } from '@mui/material';

export const MAX_OFFSETHIGHT = 65; 

export default function AutoScrollDown ({rootRef}) {
    const [show, setShow]  = useState(false);
    const handleScrollDown = useCallback(() => {
        const root = rootRef?.current;
        const top = root?.scrollHeight;
        setShow(false);
        root?.scrollTo({
            top,
            behavior: "smooth",
        });
    },[rootRef])

    useEffect(() => {
        const root = rootRef?.current
        if(root)
            root.onscroll = event => {
                const root = event.target;
                const offsetHight = root.scrollHeight - (root.scrollTop + root.offsetHeight);
                if(offsetHight <= MAX_OFFSETHIGHT && show)
                    setShow(false);
                if(offsetHight > MAX_OFFSETHIGHT && !show)
                    setShow(true);
            };
    }, [show, rootRef]);

    return (
        <Zoom in={show}>
            <Fab
                size="small"
                onClick={handleScrollDown}
                sx={{
                    position: 'absolute',
                    bottom: 15,
                    right: 15,
                    zIndex: theme => theme.zIndex.drawer
                }}
            >
                <ExpandMoreOutlinedIcon fontSize="small" />
            </Fab>
        </Zoom>
    )
}