import { useCallback, useMemo } from 'react';
import { Fab } from '@mui/material';
import CallEndOutlinedIcon from '@mui/icons-material/CallEndOutlined';
import { useSocket } from '../../../../../../utils/SocketIOProvider';
import { useDispatch, useSelector } from 'react-redux';
import answerRingtone from '../../../../../../utils/answerRingtone';
import { initializeState } from '../../../../../../redux/teleconference';

import { useTeleconference } from '../../../../../../utils/TeleconferenceProvider';

export default function HangUpButton () {
    const callId = useSelector(store => store.teleconference.callId);
    const type = useSelector(store => store.teleconference.type);
    const meetingId = useSelector(store => store.teleconference.meetingId);
    const mode = useSelector(store => store.teleconference.meetingMode);
    const targetId = useSelector(store => store.teleconference.from);
    const from = useMemo(() => 
      type === 'room' ? meetingId : targetId, 
      [meetingId, targetId, type]
    );
    const [{timers}] = useTeleconference();
    const socket = useSocket();
    const dispatch = useDispatch();

    const handleHangUp = useCallback(() => {
        const responses = {
          'incoming': 'rejected',
          'on': 'end',
          'outgoing': 'stop',
        };
        timers.forEach(timer => window.clearTimeout(timer));
        socket.emit('hang-up',{
          from, 
          type,
          details: {response: responses[mode]},
          callId,
        });
        dispatch(initializeState());
        const ringtone = answerRingtone({
          type: 'disconnect', 
          audio: new Audio(),
        });
        ringtone.loop = false;
    }, [dispatch, from, mode, socket, type, timers, callId]);

    return (
        <Fab
          color="error"
          variant="extended"
          sx={{boxShadow: 0}}
          size="small"
          onClick={handleHangUp}
        >
          <CallEndOutlinedIcon fontSize="small" />
        </Fab>
    )
}