import {
    Box as MuiBox,
    Paper,
    Stack,
    useTheme
} from '@mui/material';
import Avatar from '../../../../../components/Avatar';
import Typography from '../../../../../components/Typography';
import TextMessage from './text/TextMessage';
import MessageState from './MessageState';
import timeHumanReadable from '../../../../../utils/timeHumanReadable';
import { useMemo } from 'react';

export default function MessageBox ({
    isMine, 
    avatarSrc, 
    content,
    joinBox,
    hideAvatar,
    name, 
    type,
    sended,
    createdAt
}) {
    const theme = useTheme();
    const borderRadius = useBorderRadius(1, isMine, joinBox);
    const time = useMemo(() => { 
       const hours =  timeHumanReadable(createdAt, false, {showDetail: true});
       return hours.slice(hours.length - 5, hours.length);
    }, [createdAt]);
    
    return (
        <MuiBox>
          <MuiBox display="flex" mt={joinBox ? .25 : 2.5}>
            <Stack
                direction={isMine ? 'row-reverse' : "row" }
                display="flex"
                spacing={.5}
                justifyContent={isMine ? 'right' : 'left'}
                flex={1}
            >
                {!isMine &&
                <MuiBox
                    display="flex"
                    alignItems="end"
                    width={25}
                >
                    {!hideAvatar &&
                    <Avatar
                        sx={{
                            width: 25,
                            height: 25,
                            border: 'none',
                        }}
                        src={avatarSrc}
                        srcSet={avatarSrc}
                        alt={name}
                    />}
                </MuiBox>}
                <MuiBox maxWidth="80%" position="relative">
                    {!joinBox && 
                    <MuiBox overflow="visible">
                        <Stack 
                            direction="row" 
                            spacing={1} 
                            display="flex" 
                            justifyContent={isMine ? 'right' : 'left'}
                        >
                            {!isMine &&
                            <Typography variant="caption" color="text.secondary" >{name},</Typography>}
                            <Typography variant="caption" color="text.secondary">{time}</Typography>
                        </Stack>
                    </MuiBox>}
                    <Paper 
                        elevation={0} 
                        position="relative"
                        sx={{
                            overflow: 'hidden', 
                            background: 'none',
                            borderRadius,
                            zIndex: 0,
                        }}
                    >
    
                        {type === 'text' &&
                            <TextMessage
                                content={content}
                                bgcolor={isMine ? 
                                    theme.palette.grey[200] : 
                                'background.paper'}
                                isMine={isMine}
                                borderRadius={borderRadius}
                            />
                        }
                        {isMine && 
                        <MessageState 
                            sended={sended}
                        />}
                    </Paper>
                </MuiBox>
            </Stack>
          </MuiBox>
        </MuiBox>
    );
}

export const useBorderRadius = (radius = 1, isMine, joinBox) => {
    const theme = useTheme();
    return isMine ? 
    theme.spacing(radius, joinBox ?  0 : radius, 0, radius) : 
    theme.spacing(joinBox ? 0 : radius, radius, radius, 0);
}

MessageBox.defaultProps = {
    type: 'text',
    isMine: false,
}