import React, { useCallback, useMemo, useState } from 'react';
import { 
    Divider, 
    Toolbar
} from '@mui/material';
import ChatContactItem from '../contacts/DiscussionItem'
import { useDispatch, useSelector } from 'react-redux';
import LoadingList from './LoadingList';
import EmptyContentMessage from './EmptyContentMessage';
import { addData } from '../../../../redux/data';
import ContactListForm from './contact-list-form/ContactListForm';
import { addTeleconference } from '../../../../redux/teleconference';
import Lists from './Lists';
import db from '../../../../database/db';
import { useLiveQuery } from 'dexie-react-hooks';
import LoadingItem from '../contacts/LoadingItem';

export default function DiscussionList ({search, navigation}) {
    const [limit, setLimit] = useState(15);
    const discussions = useLiveQuery(() => 
       db.discussions.orderBy('updatedAt')
       .filter(({name}) =>
            new RegExp(
                search.trim().split(/\s/).join('|'),
                'ig'
            ).test(name)
        ).reverse()
        .limit(limit)
        .toArray()
    ,[search, limit]);

    const length = useMemo(() => discussions?.length, [discussions]);

    return (navigation === 0 &&
        <React.Fragment>
            <Toolbar variant="dense">
                <ContactListForm/>
            </Toolbar>
            <Lists
                onScrollEnd={(event, state) => {
                    if(state === 'down' && limit === length)
                        setLimit(limit + 5);
                }}
            >
                  <ListItems
                    discussions={discussions}
                    search={search}
                  />  
                  {limit === discussions && <LoadingItem/>}
             </Lists>
        </React.Fragment>
    );
}

const  ListItems = ({discussions, search}) => {
    const dispatch = useDispatch();
    const type = useSelector(store => store.teleconference.type);
    const modeId = useSelector(store => store.teleconference.meetingId);
    const target = useSelector(store => store.data?.target)
    const from = useSelector(store => store.teleconference.from);
    const callerId = useMemo(() => 
        type === 'direct' ? from : modeId, 
        [type, modeId, from]
    );
    const selected = useCallback((id) => target?.id === id, [target]);
    
    const handleClickDicussion = useCallback(data => event => {
        event.preventDefault();
        event.stopPropagation();
        dispatch(addData({key: 'target', data}));
        let params = { key: 'privileged'};
        if(callerId === data.id)
            params.data = true;
        else  params.data = false;
        if(callerId) dispatch(addTeleconference(params));
    }, [dispatch, callerId]);

    return (
        <React.Fragment> 
            <LoadingList loading={discussions === undefined}/>
            <EmptyContentMessage
                title="Aucune discussion trouvée"
                show={discussions?.length === 0}
                description={`Commencer une nouvelle discuction avec un contact.`}
            />
            {
                discussions?.map((contact, index, discussions) => (
                    <React.Fragment key={index}>
                        <ChatContactItem 
                            {...contact}
                            selected={selected(contact.id)}
                            onClick={handleClickDicussion(
                                JSON.parse(
                                    JSON.stringify(contact)
                                )
                            )}
                            search={search}
                        />
                        {index !== discussions.length - 1 && 
                        <Divider variant="inset" component="li" />
                        }
                    </React.Fragment>
                ))
            } 
        </React.Fragment>
    )
}