import { createTheme, ThemeProvider } from '@mui/material';
import { useSelector } from 'react-redux';
import Typography from '../../../../../components/Typography';
import { useLiveQuery } from 'dexie-react-hooks';
import db from '../../../../../database/db';
import { useMemo } from 'react';

export default function ContactStatus () {
    const type = useSelector(store => store.teleconference.type);
    const meetingId = useSelector(store => store.teleconference.meetingId);
    const from = useSelector(store => store.teleconference.from);
    const id = useMemo(() => 
        type === 'direct' ? from :  meetingId
        ,[from, meetingId]
    );
    const roomName = useLiveQuery(() => db.discussion?.get({id})?.name, [id]);
    const contactName = useLiveQuery(() => db.contacts?.get({id})?.name, [id]);
    const name = useMemo(() => 
        type === 'direct' ? contactName :  roomName, 
        [contactName, roomName, type]
    );

    return (
        <ThemeProvider theme={createTheme({palette: {mode: 'dark'}})}>
            <Typography
                sx={{flexGrow: 1, mx: 2}}
                children={name}
                variant="h6"
                fontWeight="bold"
            />
        </ThemeProvider>
    )
}