import db from "../database/db";
import { addData } from "../redux/data";
import store from "../redux/store";

export default async function messagesPreparing (callback) {
    const messageGrouping = [];
    const data = await db.messages.toArray();
    data.sort((a, b) => 
        new Date(b?.createdAt) - new Date(a?.createdAt) 
    );
    data.forEach(message => {
        const index = messageGrouping.findIndex(
            ({targetId}) => targetId === message.targetId
        );
        if(index === - 1) 
            messageGrouping.push({
                targetId: message?.targetId,
                messages: [message]
            });
        else messageGrouping[index].messages.push(message) ;
    });
    if(messageGrouping.length) {
        store.dispatch(addData({
            data: messageGrouping.reverse(),
            key: 'messageGrouping',
        }))
    }
    if(typeof callback === 'function')
        callback();
}