import useInfiniteScroll from "react-infinite-scroll-hook";
import { useLoadMessages } from "./useLoadMessages";
import React, { useCallback, useLayoutEffect, useMemo, useRef } from "react";
import { 
    CircularProgress,
    Fade,
    Box as MuiBox
} from "@mui/material";
import scrollBarSx from "../../../../../utils/scrollBarSx";
import AutoScrollDown, { MAX_OFFSETHIGHT } from "../AutoScrollDown";
import MessageGroupBoxByDate from "./MessageGroupBoxByDate";

function MessageContent ({rootRef: _rootRef, savedMessages}) {
  const { loading, messages, hasNextPage, error, loadMore } = useLoadMessages(savedMessages);
  const [infiniteRef, { rootRef }] = useInfiniteScroll({
    loading,
    hasNextPage,
    onLoadMore: loadMore,
    disabled: !!error,
  });
  const scrollableRootRef = useRef(null);
  const lastScrollDistanceToBottomRef = useRef();
  const reversedMessages = useMemo(() => [...messages].reverse(), [messages]);

  const reversedFirstMessageId = useMemo(() => 
    reversedMessages[0]?.id,
    [reversedMessages]
  );

  const firstMessageId = useMemo(() => 
    messages[0]?.id,
    [messages]
  );

  const loadingData = useMemo(() => 
    messages?.length !== savedMessages.length
  ,[messages, savedMessages]);

  const rootRefSetter = useCallback(
    node => {
      rootRef(node);
      scrollableRootRef.current = node;
      _rootRef.current ??= node;
    },
    [rootRef, _rootRef]
  );

  const handleRootScroll = useCallback(() => {
    const rootNode = scrollableRootRef.current;
    if (rootNode) {
      const scrollDistanceToBottom = rootNode.scrollHeight -  rootNode.scrollTop;
      lastScrollDistanceToBottomRef.current = scrollDistanceToBottom;
    }
  }, []);

  useLayoutEffect(() => {
    const scrollableRoot = scrollableRootRef.current;
    const lastScrollDistanceToBottom =
      lastScrollDistanceToBottomRef.current ?? 0;
    if (scrollableRoot) {
      scrollableRoot.scrollTop =
        scrollableRoot.scrollHeight - lastScrollDistanceToBottom;
    }
  }, [reversedFirstMessageId, rootRef]);

  useLayoutEffect(() => {
    const scrollableRoot = scrollableRootRef.current;
    if(scrollableRoot) {
      const lastScrollDistance = 
      scrollableRoot.scrollHeight - 
      scrollableRoot.scrollTop - 
      scrollableRoot.offsetHeight;
      if(lastScrollDistance <= (MAX_OFFSETHIGHT * 2)) {
        scrollableRoot.scrollTop = 
        scrollableRoot.scrollHeight + 
        scrollableRoot.offsetHeight;
      }
    }
  },[firstMessageId]);

  return (
    <React.Fragment>
      <Fade in>
        <MuiBox 
            ref={rootRefSetter} 
            onScroll={handleRootScroll}
            overflow="auto"
            width="100%"
            height="100%"
            sx={{
              ...scrollBarSx,
              zIndex: 0,
            }}
            px={2}
            py={1}
        >
          <MuiBox>
            {hasNextPage && loadingData && (
              <MuiBox 
                display="flex" 
                justifyContent="center"
                alignItems="center"
            >
              <MuiBox 
                height={25}
                width={25}
                borderRadius={50}
                bgcolor="background.paper"
                display="flex" 
                justifyContent="center"
                alignItems="center"
            >
                <CircularProgress
                    size={20}
                    color="primary"
                />
                </MuiBox>
                <MuiBox ref={infiniteRef} />
            </MuiBox>
            )}
            <MessageGroupBoxByDate
              messages={reversedMessages}
            />
          </MuiBox>
        </MuiBox>
      </Fade>
      <AutoScrollDown
          rootRef={scrollableRootRef}
      />
    </React.Fragment>
  )
}

export default MessageContent
