import { useCallback, useEffect, useLayoutEffect, useMemo, useState } from "react"
import { useSelector } from "react-redux";

const ARRAY_SIZE = 20;
const RESPONSE_TIME_IN_MS = 0;

function loadMessages(startCursor = 0, savedMessages) {
  return new Promise(resolve => {
      setTimeout(() => {
        const data = savedMessages?.slice(startCursor, startCursor + ARRAY_SIZE);
        const hasNextPage = startCursor !== savedMessages?.length;
        resolve({ hasNextPage, data });
      }, RESPONSE_TIME_IN_MS);
  });
}

export function useLoadMessages(savedMessages) {
  const [loading, setLoading] = useState(false);
  const [messages, setMessages] = useState(
    savedMessages.slice(0, ARRAY_SIZE) ?? []
  );
  const [hasNextPage, setHasNextPage] = useState(true);
  const [error, setError] = useState();
  
  const isChanged = useMemo(() => 
    messages[0]?.id !== savedMessages[0]?.id || 
    messages[0]?.updatedAt !== savedMessages[0]?.updatedAt,
    [messages, savedMessages]
  );

  const loadMore = useCallback(async () => {
      setLoading(true);
      try {
        const { data, hasNextPage: newHasNextPage } = await loadMessages(
          messages.length,
          savedMessages
        );
        setMessages(current => [...current, ...data]);
        setHasNextPage(newHasNextPage);
      } catch (err) {
        setError(err);
      } finally {
        setLoading(false);
      }
  },[loading, messages, savedMessages]);

  useLayoutEffect(() => {
    const [newMessage] = savedMessages;
    if(isChanged){
      setMessages(messages => {
        const index = messages?.findIndex(message => message.id === newMessage?.id);
        if(index === - 1)
          return [newMessage, ...messages];
        else 
          return savedMessages.slice(0, messages.length);
      });
    }
  },[isChanged, savedMessages]);

  return {loading, messages, hasNextPage, error, loadMore};
}
