import React, { useCallback, useEffect, useRef, useState } from "react";
import { 
    Box as MuiBox, Paper
} from "@mui/material";
import ToolbarFooter from "./ToolbarFooter";
import MessageEditor from "./MessageEditor";
import { EditorState, convertToRaw } from "draft-js";
import VoiceNoteEqualizer from "./voice-note-equalizer/VoiceNoteEqualizer";
import draftToHtml from 'draftjs-to-html';
import { useSocket } from "../../../../utils/SocketIOProvider";
import { useDispatch, useSelector } from "react-redux";
import db from "../../../../database/db";
import { addMessage } from "../../../../redux/data";

export default function ChatFooter () {
    const socket = useSocket();
    const [sendable, setSendable] = useState(false);
    const [editorState, setEditorState] = useState(() => EditorState.createEmpty());
    const [disabledHeader, setDisabledHeader] = useState(false);
    const [showToolbar, setShowToolbar] = useState(true);
    const textFieldRef = useRef();
    const [recording, setRecording] = useState(false);
    const target = useSelector(store => store.data?.target);
    const dispatch = useDispatch();

    const handleChange = useCallback(event => {
        setEditorState(event);
        const value = getDraftText(event);
        if(value.length && !sendable)
            setSendable(true);
        if(!value.length && sendable)
            setSendable(false);
    }, [sendable]);

    const handleToggleRecording = useCallback(() => 
        setRecording(recording => !recording), 
    []);
    
    const handleSendMessage = useCallback(async() => {
        if(getDraftText(editorState)) {
            const rawContentState = convertToRaw(editorState.getCurrentContent());
            const content = draftToHtml(rawContentState);
            const id = (Date.now() + 1).toString(16) + target.id;
            const messageType = 'text';
            const date = new Date().toString();
            const message = {
                id,
                type: messageType,
                targetId: target.id,
                content,
                avatarSrc: null,
                createdAt: date,
                isMine: true,
                sended: false,
                timeout: 5000
            };
            handleChange(
                EditorState.moveFocusToEnd(
                    EditorState.createEmpty()
                )
            );
            await db.messages.add(message);
            await db.discussions.update(target?.id, {
                lastNotice: message,
                updatedAt: new Date(date),
            });
            socket?.emit(`${target.type}-message`, {
                content, 
                to: target?.id,
                date,
                type: messageType,
                clientId: id,
            });
            dispatch(addMessage({message}));
        }
    }, [target, editorState, handleChange, socket, dispatch]);

    useEffect(() => {
        if(target)
            textFieldRef.current?.focus();
    }, [textFieldRef, target]);
  
  return (
    <MuiBox
        bgcolor="background.paper"
        p={1}
        display="flex"
        width="100%"
        alignItems="center"
        justifyContent="center"
        flexDirection="column"
        overflow="hidden"
        position="relative"
        sx={{
            borderTop: theme => `1px solid ${theme.palette.divider}`,
            zIndex: theme => theme.zIndex.appBar
        }}
    >
        <Paper
            sx={{
                display: 'flex',
                border: (theme) => `1px solid ${theme.palette.divider}`,
                flexWrap: 'wrap',
                flexDirection: 'column',
                width: '100%',
                transition: 'none'
            }}
            elevation={disabledHeader ? 0 : 2}
        >
            <MessageEditor
                handleChange={handleChange}
                editorState={editorState}
                disabledHeader={disabledHeader} 
                setDisabledHeader={setDisabledHeader}
                textFieldRef={textFieldRef}
                showToolbar={showToolbar}
                handleSendMessage={handleSendMessage}
                target={target}
            />
            <ToolbarFooter
                sendable={sendable}
                showToolbar={showToolbar}
                handleChange={handleChange}
                editorState={editorState}
                toggleShowToolbar={(event, value) => setShowToolbar(value)}
                handleToggleRecording={handleToggleRecording}
                handleSendMessage={handleSendMessage}
            />
        </Paper>
        {recording && 
        <VoiceNoteEqualizer
            handleToggleRecording={handleToggleRecording}
        />}
    </MuiBox>
  );
}

export const getDraftText = event => convertToRaw(
    event.getCurrentContent()
)?.blocks.map(({text}) => text).join('\n').trim();