import useInfiniteScroll from "react-infinite-scroll-hook";
import { useLoadMessages } from "./useLoadMessages";
import { useCallback, useEffect, useMemo, useRef } from "react";
import { 
    CircularProgress,
    Box as MuiBox
} from "@mui/material";


function MessageContent () {
  const { loading, messages, hasNextPage, error, loadMore } = useLoadMessages();
  const [infiniteRef, { rootRef }] = useInfiniteScroll({
    loading,
    hasNextPage,
    onLoadMore: loadMore,
    disabled: !!error,
  });
  const scrollableRootRef = useRef(null);
  const lastScrollDistanceToBottomRef = useRef();
  const reversedMessages = useMemo(() => [...messages].reverse(), [messages]);
  useEffect(() => {
    const scrollableRoot = scrollableRootRef.current;
    const lastScrollDistanceToBottom =
      lastScrollDistanceToBottomRef.current ?? 0;
    if (scrollableRoot) {
      scrollableRoot.scrollTop =
        scrollableRoot.scrollHeight - lastScrollDistanceToBottom;
    }
  }, [reversedMessages, rootRef]);

  const rootRefSetter = useCallback(
    node => {
      rootRef(node);
      scrollableRootRef.current = node;
    },
    [rootRef]
  );

  const handleRootScroll = useCallback(() => {
    const rootNode = scrollableRootRef.current;
    if (rootNode) {
      const scrollDistanceToBottom = rootNode.scrollHeight - rootNode.scrollTop;
      lastScrollDistanceToBottomRef.current = scrollDistanceToBottom;
    }
  }, []);

  return (
    <MuiBox 
        ref={rootRefSetter} 
        onScroll={handleRootScroll}
        overflow="auto"
    >
      <MuiBox>
        {hasNextPage && (
          <MuiBox 
            ref={infiniteRef} 
            display="flex" 
            justifyContent="center"
            alignContent="center"
            py={.5}
        >
            <CircularProgress
                size={15}
                color="inherit"
            />
          </MuiBox>
        )}
        {reversedMessages.map(item => (
          <div key={item.key}>{item.content}</div>
        ))}
      </MuiBox>
    </MuiBox>
  )
}

export default MessageContent
