import { createSlice } from "@reduxjs/toolkit";
import { isEqual } from "lodash";

const initialState = {
    target: null,
    messages: [],
    messageGrouping: [],
    conversations: null,
    notifications: null,
    status: {},
    contacts: null,
    calls: null,
    chatGroups: null,
    search: '',
};

const data = createSlice({
    name: 'data',
    initialState,
    reducers: {
        addData(state, actions) {
            const { key, data } = actions.payload;
            if(key === 'data')
                Object.keys(data).forEach(_key => {
                        state[_key] = data[_key]
                });
            else state[key] = data;
            const target = (key === 'target' && data) || data?.target;
            if(target) {
                state.target = {
                    ...target,
                    status: state.status[target.id],
                }
                const messages = state.messageGrouping?.find(
                    message => message.targetId === target.id
                )?.messages;
                state.messages = messages || [];
            }
        },
        addMessage(state, actions) {
            const { message } = actions.payload;
            const index = state.messageGrouping.findIndex(
                ({targetId}) => targetId === message.targetId
            );

            if(state.target?.id === message?.targetId) {
                if(index === - 1)
                    state.messages = [message];
                else {
                    const subIndex = state.messages.findIndex(({id}) => id === message.id);
                    if(subIndex === - 1) 
                        state.messages = [message, ...state.messages];
                     else {
                        const oldMessage = state.messages[subIndex];
                        const oldTime = (new Date(oldMessage.updatedAt)).getTime();
                        const newTime = (new Date(message.updatedAt)).getTime();
                        if(newTime !== oldTime) 
                            state.messages[subIndex] = message;
                            state.messages = [...state.messages];
                    }
                }
            }
            if(index === - 1)
                state.messageGrouping.push({
                    targetId: message.targetId,
                    messages: [message]
                });
            else {
                const oldData = state.messageGrouping[index];
                const subIndex = oldData.messages.findIndex(({id}) => id === message.id);
                if(subIndex === - 1) 
                    oldData.messages = [message, ...oldData.messages];
                else {
                    const oldMessage = oldData.messages[subIndex];
                    const oldTime = (new Date(oldMessage.updatedAt)).getTime();
                    const newTime = (new Date(message.updatedAt)).getTime();
                    if(newTime !== oldTime)
                        oldData.messages[subIndex] = message
                }
                state.messageGrouping = [...state.messageGrouping];
            }
        },
        setStatus(state, actions) {
            const { id, status } = actions.payload;
            state.status[id] = status;
            if(state.target?.id === id)
                state.target.status = status;
        },
        addNotification(state, actions) {
            const { data } = actions.payload;
            if(state.notifications === null) 
                state.notifications = [data];
            else if (
                JSON.stringify(
                    state.notifications
                    ?.find(({id}) => id === data?.id)
                ) !== JSON.stringify(data)
            ) state.notifications = [
                ...state.notifications, 
                data
            ];
            if(data?.children?.length === 0)
                state.notifications = [...state.notifications]
                .filter(({id}) => id !== data?.id);
        },
        updateChat(state, actions) {
            const { targetId, message } = actions.payload;
            const conversations = [...state.conversations];
            const targetConversation = conversations?.find(({id}) => id === targetId);
            const savedMessages = targetConversation?.origin?.messages;
            const index = savedMessages.findIndex(({_id}) => message?._id === _id);
            if(index > -1) {
                const lastSavedMessage = savedMessages[savedMessages.length - 1];
                const isNotEqual = !isEqual(lastSavedMessage, message);
                if(isNotEqual) {
                    savedMessages[index] = message;
                    targetConversation.updatedAt = message?.createdAt;
                    targetConversation.lastNotice = message?.content;
                    state.conversations = [...conversations];
                }
            } else {
                savedMessages?.push(message);
                targetConversation.updatedAt = message?.createdAt;
                targetConversation.lastNotice = message?.content;
                state.conversations = [...conversations];
            }
        }
    }
});

export const { 
        addData, 
        addNotification, 
        updateChat, 
        setStatus, 
        addMessage,
        loadMoreMessages
     } = data.actions;
export default data.reducer;