import {
    Box as MuiBox
} from '@mui/material';
import { useMemo, useRef } from 'react';
import { useSelector } from 'react-redux';
import MessageContent from './message-box/MessageContent';

export default function ChatBody () {
    const rootRef = useRef();
    const savedMessages = useSelector(store => store.data.messages);
    const key = useMemo(() => savedMessages[0]?.targetId, [savedMessages]);

    return ( 
        <MuiBox
            overflow="hidden"
            display="flex"
            position="relative"
            sx={{
                zIndex: theme => theme.zIndex.drawer,
            }}
            flex={1}
        >
            <MessageContent
                rootRef={rootRef}
                savedMessages={savedMessages}
                key={key}
            />  
        </MuiBox>
    )
}